script:
frappe.ui.form.on('Quotation', {
    refresh: function(frm) {
        // Triggers whenever a row inside the 'items' grid is clicked/selected
        frm.fields_dict.items.grid.wrapper.on('click', '.grid-row', function() {
            let row = frm.fields_dict.items.grid.get_selected_children();

            if (row && row.length > 0) {
                // Pulls description from the currently active row
                frm.set_value('specification', row[0].description);
            }
        });
    }
});

// Separate trigger to capture immediately when item code or description changes
frappe.ui.form.on('Quotation Item', {
    item_code: function(frm, cdt, cdn) {
        let row = frappe.get_doc(cdt, cdn);
        // Timeout ensures the framework finishes fetching the standard item description first
        setTimeout(() => {
            if (row && row.description) {
                frm.set_value('specification', row.description);
            }
        }, 500);
    },
    description: function(frm, cdt, cdn) {
        let row = frappe.get_doc(cdt, cdn);
        if (row && row.description) {
            frm.set_value('specification', row.description);
        }
    }
});

frappe.ui.form.on('Optional Quotation Item', {
    item_code: function(frm, cdt, cdn) {
        let child = locals[cdt][cdn];
        if (!child.item_code) return;

        // 1. Fetch Item Name and Description from the Item Master
        frappe.db.get_value('Item', child.item_code, ['item_name', 'description'], (r) => {
            if (r) {
                frappe.model.set_value(cdt, cdn, 'item_name', r.item_name || child.item_code);
                frappe.model.set_value(cdt, cdn, 'description', r.description || '');
            }

            // 2. Fetch Price List Rate from Item Price list using the Quotation's active Price List
            let current_price_list = frm.doc.selling_price_list || 'Standard Selling';

            frappe.db.get_value('Item Price', 
                { 'item_code': child.item_code, 'price_list': current_price_list }, 
                'price_list_rate', 
                (p) => {
                    if (p && p.price_list_rate) {
                        frappe.model.set_value(cdt, cdn, 'rate', p.price_list_rate);
                    } else {
                        frappe.model.set_value(cdt, cdn, 'rate', 0); // Reset to 0 if no price list found
                    }

                    // 3. Force Quantity to default to 1 if empty
                    if (!child.qty) {
                        frappe.model.set_value(cdt, cdn, 'qty', 1);
                    }

                    // 4. Fire math calculations
                    calculate_manual_vat(frm, cdt, cdn);
                }
            );
        });
    },
    qty: function(frm, cdt, cdn) {
        calculate_manual_vat(frm, cdt, cdn);
    },
    rate: function(frm, cdt, cdn) {
        calculate_manual_vat(frm, cdt, cdn);
    }
});

function calculate_manual_vat(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    let qty = flt(row.qty, 2);
    let rate = flt(row.rate, 2);

    // 1. Calculate Base Amount (rounded to 2 decimal places)
    let amount = flt(qty * rate, 2);
    frappe.model.set_value(cdt, cdn, 'amount', amount);

    // 2. Calculate 15% VAT Amount (explicitly rounded to 2 decimal places)
    let vat_amount = flt(amount * 0.15, 2);
    frappe.model.set_value(cdt, cdn, 'vat_amount', vat_amount);

    // 3. Calculate Final Total (explicitly rounded to 2 decimal places)
    let total_with_vat = flt(amount + vat_amount, 2);
    frappe.model.set_value(cdt, cdn, 'total_with_vat', total_with_vat);

    // Refresh child grid layer UI
    frm.refresh_field('additional_items');
}

frappe.ui.form.on('Optional Quotation Item', {
    qty: function(frm, cdt, cdn) {
        calculate_row_totals(frm, cdt, cdn);
    },
    rate: function(frm, cdt, cdn) {
        calculate_row_totals(frm, cdt, cdn);
    },
    vat_percentage: function(frm, cdt, cdn) {
        calculate_row_totals(frm, cdt, cdn);
    }
});

function calculate_row_totals(frm, cdt, cdn) {
    let child = locals[cdt][cdn];

    // 1. Calculate Base Amount (Qty * Rate)
    let amount = (child.qty || 0) * (child.rate || 0);
    frappe.model.set_value(cdt, cdn, 'amount', amount);

    // 2. Calculate Total with VAT
    let vat_percent = child.vat_percentage || 0;
    let total_with_vat = amount * (1 + (vat_percent / 100));

    frappe.model.set_value(cdt, cdn, 'total_with_vat', total_with_vat);
}

frappe.ui.form.on('Quotation Item', {
    item_code: function(frm, cdt, cdn) {
        let child = locals[cdt][cdn];
        if (!child.item_code) return;

        // 1. Instantly reach into the Item master database to get your custom field
        frappe.db.get_value('Item', child.item_code, 'specification', (r) => {
            if (r && r.specification) {
                // 2. Save it down to the child row custom field
                frappe.model.set_value(cdt, cdn, 'specification', r.specification);

                // 3. Simultaneously push it up to the parent Quotation form field
                frm.set_value('specification', r.specification);
            }
        });
    },

    // Triggers cleanly when a user explicitly clicks or selects a row in the grid natively
    items_on_form_render: function(frm, cdt, cdn) {
        let child = locals[cdt][cdn];
        if (child && child.specification) {
            // Sync the parent form specification block whenever a row is actively opened/focused
            frm.set_value('specification', child.specification);
        }
    }
});

frappe.ui.form.on('Quotation Item', {
    item_code: function(frm, cdt, cdn) {
        let child = locals[cdt][cdn];

        // 1. If item_code is cleared, wipe both specification fields immediately
        if (!child.item_code) {
            frappe.model.set_value(cdt, cdn, 'specification', '');
            frm.set_value('specification', '');
            return;
        }

        // 2. Clear old values first so a slow database check doesn't leave ghost data
        frappe.model.set_value(cdt, cdn, 'specification', '');
        frm.set_value('specification', '');

        // 3. Reach into database to find the new item's specification
        frappe.db.get_value('Item', child.item_code, 'specification', (r) => {
            if (r && r.specification) {
                frappe.model.set_value(cdt, cdn, 'specification', r.specification);
                frm.set_value('specification', r.specification);
            }
            // If the item has no specification, it safely stays blank now
        });
    },
    items_on_form_render: function(frm, cdt, cdn) {
        let child = locals[cdt][cdn];
        // Only sync to parent if a specification actively exists, otherwise clear parent field
        if (child && child.specification) {
            frm.set_value('specification', child.specification);
        } else {
            frm.set_value('specification', '');
        }
    }
});

frappe.ui.form.on('Optional Quotation Item', {
    // 1. Changed listener from item_code to custom_item_code to avoid ERPNext core crashes
    custom_item_code: function(frm, cdt, cdn) {
        let child = locals[cdt][cdn];

        // Immediate reset of dependent fields on change
        frappe.model.set_value(cdt, cdn, 'item_name', '');
        frappe.model.set_value(cdt, cdn, 'description', '');
        frappe.model.set_value(cdt, cdn, 'rate', 0);
        frappe.model.set_value(cdt, cdn, 'specification', '');
        frm.set_value('specification', '');

        if (!child.custom_item_code) {
            calculate_manual_vat(frm, cdt, cdn);
            return;
        }

        // Fetch Item details using the renamed custom_item_code field
        frappe.db.get_value('Item', child.custom_item_code, ['item_name', 'description', 'specification'], (r) => {
            if (r) {
                frappe.model.set_value(cdt, cdn, 'item_name', r.item_name || child.custom_item_code);
                frappe.model.set_value(cdt, cdn, 'description', r.description || '');
                frappe.model.set_value(cdt, cdn, 'specification', r.specification || '');

                if (r.specification) {
                    frm.set_value('specification', r.specification);
                }
            }

            // Fetch Price List Rate safely
            let current_price_list = frm.doc.selling_price_list || 'Standard Selling';
            frappe.db.get_value('Item Price', 
                { 'item_code': child.custom_item_code, 'price_list': current_price_list }, 
                'price_list_rate', 
                (p) => {
                    if (p && p.price_list_rate) {
                        frappe.model.set_value(cdt, cdn, 'rate', p.price_list_rate);
                    } else {
                        frappe.model.set_value(cdt, cdn, 'rate', 0);
                    }

                    if (!child.qty) {
                        frappe.model.set_value(cdt, cdn, 'qty', 1);
                    }

                    calculate_manual_vat(frm, cdt, cdn);
                }
            );
        });
    },
    qty: function(frm, cdt, cdn) {
        calculate_manual_vat(frm, cdt, cdn);
    },
    rate: function(frm, cdt, cdn) {
        calculate_manual_vat(frm, cdt, cdn);
    },
    additional_items_on_form_render: function(frm, cdt, cdn) {
        let child = locals[cdt][cdn];
        if (child && child.specification) {
            frm.set_value('specification', child.specification);
        } else {
            frm.set_value('specification', '');
        }
    }
});

function calculate_manual_vat(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    let qty = flt(row.qty, 2);
    let rate = flt(row.rate, 2);

    let amount = flt(qty * rate, 2);
    frappe.model.set_value(cdt, cdn, 'amount', amount);

    let vat_amount = flt(amount * 0.15, 2);
    frappe.model.set_value(cdt, cdn, 'vat_amount', vat_amount);

    let total_with_vat = flt(amount + vat_amount, 2);
    frappe.model.set_value(cdt, cdn, 'total_with_vat', total_with_vat);

    frm.refresh_field('additional_items');
}

frappe.ui.form.on('Inspection_M', {
    refresh: function(frm) {
        setup_image_zoom(frm);
    },
    selected_image_source: function(frm) {
        setup_image_zoom(frm);
    }
});

function setup_image_zoom(frm) {
    setTimeout(function() {
        if (frm.fields_dict.dynamic_preview_image) {
            let wrapper = frm.fields_dict.dynamic_preview_image.wrapper;

            if (wrapper) {
                wrapper.style.cursor = 'zoom-in';

                wrapper.onclick = function(e) {
                    e.preventDefault();
                    e.stopPropagation();

                    let rendered_img = wrapper.querySelector('img');
                    let active_src = rendered_img ? rendered_img.getAttribute('src') : frm.doc.selected_image_source;

                    if (!active_src || active_src.includes('broken-image') || active_src === '') {
                        frappe.msgprint(__('Please capture or select a microscope image before zooming.'));
                        return;
                    }

                    if (!active_src.startsWith('http')) {
                        active_src = window.location.origin + active_src;
                    }

                    let d = new frappe.ui.Dialog({
                        title: frm.doc.caption || 'Microscope View',
                        size: 'large',

                        on_page_show: function() {
                            let zoom_img = document.getElementById('microscope-fullscreen-viewport');
                            let viewport = document.getElementById('zoom-container-viewport');
                            let current_scale = 1.0;
                            let initial_distance = 0;

                            if (!zoom_img || !viewport) return; 

                            // Update scale factor dynamically
                            function update_zoom_layer(scale_value) {
                                current_scale = Math.max(1.0, Math.min(scale_value, 5.0));
                                zoom_img.style.width = (current_scale * 100) + '%';
                            }

                            // --- BUTTON ACTIONS ---
                            document.getElementById('zoom-in-btn').onclick = function() {
                                update_zoom_layer(current_scale + 0.5);
                            };

                            document.getElementById('zoom-out-btn').onclick = function() {
                                update_zoom_layer(current_scale - 0.5);
                            };

                            document.getElementById('zoom-reset-btn').onclick = function() {
                                update_zoom_layer(1.0);
                                viewport.scrollLeft = 0;
                                viewport.scrollTop = 0;
                            };

                            // --- PINCH AND PAN MULTITOUCH HANDLING ---
                            viewport.addEventListener('touchstart', function(evt) {
                                if (evt.touches.length === 2) {
                                    evt.preventDefault();
                                    let t1 = evt.touches[0];
                                    let t2 = evt.touches[1];
                                    initial_distance = Math.hypot(t1.pageX - t2.pageX, t1.pageY - t2.pageY);
                                }
                            }, { passive: false });

                            viewport.addEventListener('touchmove', function(evt) {
                                if (evt.touches.length === 2 && initial_distance > 0) {
                                    evt.preventDefault();
                                    let t1 = evt.touches[0];
                                    let t2 = evt.touches[1];
                                    let current_distance = Math.hypot(t1.pageX - t2.pageX, t1.pageY - t2.pageY);

                                    let factor = current_distance / initial_distance;
                                    update_zoom_layer(current_scale * factor);
                                }
                            }, { passive: false });

                            viewport.addEventListener('touchend', function(evt) {
                                if (evt.touches.length < 2) {
                                    initial_distance = 0;
                                }
                            });
                        }
                    });

                    // FIXED: Changed height: 60vh to max-height: 65vh + height: auto to drop empty space
                    d.body.innerHTML = `
                        <div id="zoom-container-viewport" style="width: 100%; max-height: 65vh; height: auto; overflow: auto; background: #000; border-radius: 6px; position: relative; -webkit-overflow-scrolling: touch;">
                            <img src="${active_src}" id="microscope-fullscreen-viewport" style="width: 100%; height: auto; display: block; margin: 0 auto; user-select: none; -webkit-user-drag: none; transition: width 0.1s ease-out;">
                        </div>
                        <div style="display: flex; justify-content: center; gap: 15px; margin-top: 15px;">
                            <button id="zoom-in-btn" class="btn btn-sm btn-primary" style="font-weight: bold; width: 55px; height: 40px; font-size: 16px;">＋</button>
                            <button id="zoom-out-btn" class="btn btn-sm btn-default" style="font-weight: bold; width: 55px; height: 40px; font-size: 16px; border: 1px solid #d1d8dd;">－</button>
                            <button id="zoom-reset-btn" class="btn btn-sm btn-danger" style="font-size: 12px; height: 40px; padding: 0 12px;">Reset</button>
                        </div>
                    `;

                    d.show();
                };
            }
        }
    }, 300);
}

frappe.ui.form.on('Inspection_M', {
    refresh: function(frm) {
        setup_image_zoom(frm);
    },
    selected_image_source: function(frm) {
        setup_image_zoom(frm);
    }
});

function setup_image_zoom(frm) {
    setTimeout(function() {
        if (frm.fields_dict.dynamic_preview_image) {
            let wrapper = frm.fields_dict.dynamic_preview_image.wrapper;

            if (wrapper) {
                wrapper.style.cursor = 'zoom-in';

                wrapper.onclick = function(e) {
                    e.preventDefault();
                    e.stopPropagation();

                    // DIRECT DOM CHECK: Pull the live image path directly from the rendered on-screen thumbnail
                    let rendered_img = wrapper.querySelector('img');
                    let active_src = rendered_img ? rendered_img.getAttribute('src') : frm.doc.selected_image_source;

                    // Fallback block if no valid image string could be read
                    if (!active_src || active_src.includes('broken-image') || active_src === '') {
                        frappe.msgprint(__('Please capture or select a microscope image before zooming.'));
                        return;
                    }

                    // Complete the URL structure if it uses a relative server folder path
                    if (!active_src.startsWith('http')) {
                        active_src = window.location.origin + active_src;
                    }

                    // Open full image view inside a modal container layout cleanly
                    let d = new frappe.ui.Dialog({
                        title: frm.doc.caption || 'Microscope Zoom View',
                        size: 'large'
                    });

                    d.body.innerHTML = `
                        <div style="text-align: center; padding: 10px; background-color: #f9f9f9;">
                            <img src="${active_src}" style="width: 100%; height: auto; border-radius: 6px; box-shadow: 0px 4px 12px rgba(0,0,0,0.15);">
                        </div>
                    `;
                    d.show();
                };
            }
        }
    }, 300); // 300ms layout placement window
}

frappe.ui.form.on('Inspection_M', {
    refresh: function(frm) {
        setup_image_zoom(frm);
    },
    selected_image_source: function(frm) {
        setup_image_zoom(frm);
    }
});

function setup_image_zoom(frm) {
    setTimeout(function() {
        if (frm.fields_dict.dynamic_preview_image) {
            let wrapper = frm.fields_dict.dynamic_preview_image.wrapper;

            if (wrapper) {
                // Apply visual cue style to hint it is a tap-to-expand field
                wrapper.style.cursor = 'zoom-in';

                wrapper.onclick = function(e) {
                    e.preventDefault();
                    e.stopPropagation();

                    // Read active target path directly from the rendered thumbnail
                    let rendered_img = wrapper.querySelector('img');
                    let active_src = rendered_img ? rendered_img.getAttribute('src') : frm.doc.selected_image_source;

                    if (!active_src || active_src.includes('broken-image') || active_src === '') {
                        frappe.msgprint(__('Please capture or select a microscope image before zooming.'));
                        return;
                    }

                    // Append server domain origin fallback if path is local/relative
                    if (!active_src.startsWith('http')) {
                        active_src = window.location.origin + active_src;
                    }

                    // Create an ultra-wide native Frappe Dialogue Container
                    let d = new frappe.ui.Dialog({
                        title: frm.doc.caption || 'Microscope View (Pinch to Zoom)',
                        size: 'large'
                    });

                    // Inject a pure viewport-responsive layout container
                    d.body.innerHTML = `
                        <div style="width: 100%; max-height: 70vh; overflow: auto; text-align: center; padding: 5px; background: #111; border-radius: 6px;">
                            <img src="${active_src}" id="microscope-fullscreen-viewport" style="width: 100%; height: auto; max-width: none; transition: transform 0.2s ease; cursor: grab; display: inline-block;">
                        </div>
                        <div style="display: flex; justify-content: center; gap: 15px; margin-top: 12px;">
                            <button id="zoom-in-btn" class="btn btn-sm btn-primary" style="font-weight: bold; width: 45px;">＋</button>
                            <button id="zoom-out-btn" class="btn btn-sm btn-default" style="font-weight: bold; width: 45px;">－</button>
                            <button id="zoom-reset-btn" class="btn btn-sm btn-danger" style="font-size: 11px;">Reset</button>
                        </div>
                    `;
                    d.show();

                    // --- TOUCH & BUTTON ZOOM LOGIC HUB ---
                    let zoom_img = document.getElementById('microscope-fullscreen-viewport');
                    let current_scale = 1.0;

                    // Manual Adjustment Triggers (Backup for gloves or wet hands)
                    document.getElementById('zoom-in-btn').onclick = function() {
                        current_scale += 0.25;
                        zoom_img.style.transform = `scale(${current_scale})`;
                    };

                    document.getElementById('zoom-out-btn').onclick = function() {
                        if (current_scale > 0.5) {
                            current_scale -= 0.25;
                            zoom_img.style.transform = `scale(${current_scale})`;
                        }
                    };

                    document.getElementById('zoom-reset-btn').onclick = function() {
                        current_scale = 1.0;
                        zoom_img.style.transform = `scale(1.0)`;
                    };
                };
            }
        }
    }, 300);
}

frappe.ui.form.on('Inspection_M', {
    refresh: function(frm) {
        setup_image_zoom(frm);
    },
    selected_image_source: function(frm) {
        setup_image_zoom(frm);
    }
});

function setup_image_zoom(frm) {
    setTimeout(function() {
        if (frm.fields_dict.dynamic_preview_image) {
            let wrapper = frm.fields_dict.dynamic_preview_image.wrapper;

            if (wrapper) {
                wrapper.style.cursor = 'zoom-in';

                wrapper.onclick = function(e) {
                    e.preventDefault();
                    e.stopPropagation();

                    // Safely extract active target file path string
                    let rendered_img = wrapper.querySelector('img');
                    let active_src = rendered_img ? rendered_img.getAttribute('src') : frm.doc.selected_image_source;

                    if (!active_src || active_src.includes('broken-image') || active_src === '') {
                        frappe.msgprint(__('Please capture or select a microscope image before zooming.'));
                        return;
                    }

                    if (!active_src.startsWith('http')) {
                        active_src = window.location.origin + active_src;
                    }

                    // Native Dialog with lifecycle hook rendering pipeline
                    let d = new frappe.ui.Dialog({
                        title: frm.doc.caption || 'Microscope View (Pinch & Tap to Zoom)',
                        size: 'large',

                        // THIS CRITICAL HOOK FIXES UNRESPONSIVE BUTTONS
                        on_page_show: function() {
                            let zoom_img = document.getElementById('microscope-fullscreen-viewport');
                            let viewport = document.getElementById('zoom-container-viewport');
                            let current_scale = 1.0;
                            let initial_distance = 0;

                            if (!zoom_img) return; // Guard clause 

                            // --- BUTTON WORKFLOW CONTROLS ---
                            document.getElementById('zoom-in-btn').onclick = function() {
                                current_scale = Math.min(current_scale + 0.4, 6.0);
                                zoom_img.style.transform = 'scale(' + current_scale + ')';
                            };

                            document.getElementById('zoom-out-btn').onclick = function() {
                                current_scale = Math.max(current_scale - 0.4, 0.4);
                                zoom_img.style.transform = 'scale(' + current_scale + ')';
                            };

                            document.getElementById('zoom-reset-btn').onclick = function() {
                                current_scale = 1.0;
                                zoom_img.style.transform = 'scale(1.0)';
                            };

                            // --- PINCH TO ZOOM TOUCH CONTROL HUB ---
                            function get_distance(touches) {
                                return Math.hypot(touches[0].pageX - touches[1].pageX, touches[0].pageY - touches[1].pageY);
                            }

                            viewport.addEventListener('touchstart', function(evt) {
                                if (evt.touches.length === 2) {
                                    evt.preventDefault();
                                    initial_distance = get_distance(evt.touches);
                                }
                            }, { passive: false });

                            viewport.addEventListener('touchmove', function(evt) {
                                if (evt.touches.length === 2 && initial_distance > 0) {
                                    evt.preventDefault();
                                    let current_distance = get_distance(evt.touches);
                                    let factor = current_distance / initial_distance;
                                    let target_scale = current_scale * factor;

                                    if (target_scale >= 0.4 && target_scale <= 6.0) {
                                        zoom_img.style.transform = 'scale(' + target_scale + ')';
                                    }
                                }
                            }, { passive: false });

                            viewport.addEventListener('touchend', function(evt) {
                                if (evt.touches.length < 2) {
                                    let transform_string = zoom_img.style.transform;
                                    let match = transform_string.match(/scale\(([^)]+)\)/);
                                    if (match && match[1]) {
                                        current_scale = parseFloat(match[1]);
                                    }
                                    initial_distance = 0;
                                }
                            });
                        }
                    });

                    // Injected clean layout structure markup
                    d.body.innerHTML = `
                        <div id="zoom-container-viewport" style="width: 100%; max-height: 60vh; overflow: auto; text-align: center; padding: 5px; background: #111; border-radius: 6px; touch-action: none;">
                            <img src="${active_src}" id="microscope-fullscreen-viewport" style="width: 100%; height: auto; max-width: none; transform-origin: center center; transition: transform 0.08s ease-out; display: inline-block;">
                        </div>
                        <div style="display: flex; justify-content: center; gap: 15px; margin-top: 15px; padding-bottom: 5px;">
                            <button id="zoom-in-btn" class="btn btn-sm btn-primary" style="font-weight: bold; width: 55px; height: 38px; font-size: 16px;">＋</button>
                            <button id="zoom-out-btn" class="btn btn-sm btn-default" style="font-weight: bold; width: 55px; height: 38px; font-size: 16px; border: 1px solid #d1d8dd;">－</button>
                            <button id="zoom-reset-btn" class="btn btn-sm btn-danger" style="font-size: 12px; height: 38px; padding: 0 10px;">Reset</button>
                        </div>
                    `;

                    d.show();
                };
            }
        }
